insert into public.fornitori
  (ragione_sociale,indirizzo,citta,cap,provincia,nazione,email,referente,telefono,partita_iva,codice_fiscale,codice_sdi,pec,iban,note,attivo)
select d.rs,d.ind,d.citta,d.cap,d.prov,coalesce(nullif(d.naz,''),'Italia'),
       d.email,d.ref,d.tel,d.piva,d.cf,d.sdi,d.pec,d.iban,nullif(d.note,''),true
from dati d
where d.rs <> ''
  and not exists (select 1 from public.fornitori f where d.piva <> '' and f.partita_iva = d.piva)
  and not exists (select 1 from public.fornitori f where lower(f.ragione_sociale) = lower(d.rs));
